#include <bits/stdc++.h>
using namespace std;

#define int long long 

int func(int x, int y, vector <int> & pref, int n) {
    int z = (3*n) - (2*x) - y;
    int sum1 = 2*pref[x]; 
    int sum2 = pref[x+ (2*y)];
    int sum3 = pref[z]*3;
    return sum1 + sum2 + sum3;
}

void solve() {
    int n;
    cin >> n;
    vector <int> v(3*n);
    for(int i = 0; i < 3*n; i++) {
        cin >> v[i];
    }
    sort(v.rbegin(), v.rend());
    vector <int> pref(3*n+1);
    for(int i = 0; i < 3*n; i++) {
        pref[i+1] = pref[i] + v[i];
    }
    int ans = 0;
    for(int i = 0; i <= n; i++) {
        int x = i;
        int low = 0, high = n-i;
        // int temp = 0;
        while(low < high) {
            int mid = (low + high) / 2;
            int y = mid;
            // cout << x << " " << y << endl;
            int ans1 = func(x, y, pref, n);
            int ans2 = func(x, y+1, pref, n);
            if(ans1 >= ans2) {
                // temp = max(temp, ans1);
                high = mid;
            }
            else {
                // temp = max(temp, ans2);
                low = mid + 1;
            }
        }
        ans = max(ans, func(x, low, pref, n));
    }
    // cout << func(0, 0, 1 , pref) << endl;
    cout << ans << endl;
    
}

signed main() {
    int t;
    cin >> t;
    while(t--) {
        solve();
    }
    return 0;
}
